import{_ as e,o as l,c as t,O as p}from"./chunks/framework.ac0f74f3.js";const i="/assets/cpj-zr-zjrw2.e353ecab.png",r="/assets/cpj-zr-zjrw.55c41103.png",q=JSON.parse('{"title":"过程检安排","description":"","frontmatter":{},"headers":[],"relativePath":"品质管理/过程检安排.md","filePath":"品质管理/过程检安排.md"}'),o={name:"品质管理/过程检安排.md"};function s(n,a,h,c,u,d){return l(),t("div",null,[...a[0]||(a[0]=[p('<h1 id="过程检安排" tabindex="-1">过程检安排 <a class="header-anchor" href="#过程检安排" aria-label="Permalink to &quot;过程检安排&quot;">​</a></h1><blockquote><p>生产完成员工报工时，如果这个工序配置了检验项时，会带到过程检安排列表</p></blockquote><h4 id="_1-批量分发" tabindex="-1">1.批量分发 <a class="header-anchor" href="#_1-批量分发" aria-label="Permalink to &quot;1.批量分发&quot;">​</a></h4><ul><li><p>先勾选序号前的勾选框，点击批量分发按钮即可</p><p>-单号与工序均不一致的情况下，不能批量分发</p></li><li><p>选择检验类型，检验员，分发量，要求完成时间，备注信息等可提交分发</p><p>-全检指的是检验所有的产品</p><p>-抽检指的是输入百分比抽取部分产品进行检验</p><p>-免检指的是不用检验直接入库</p></li><li><p>一个任务可分发多个检验员，如果选择多明检验员时，填写分发量时，在弹窗中分配分发数量</p></li></ul><h4 id="_2-分发" tabindex="-1">2.分发 <a class="header-anchor" href="#_2-分发" aria-label="Permalink to &quot;2.分发&quot;">​</a></h4><ul><li><p>点击分发按钮选择检验类型，要求完成时间</p></li><li><p>可添加给多个检验人员</p><p>-鼠标悬浮在序号区域显示添加/删除按钮，可添加或删除检验员</p><p>-分发数量不能超过送检量</p></li><li><p>检验类型分为全检、抽检、免检</p><p>-全检指的是检验所有的产品</p><p>-抽检指的是输入百分比抽取部分产品进行检验</p><p>-免检指的是不用检验直接入库</p></li></ul><h4 id="_3-表头自定义设置" tabindex="-1">3.表头自定义设置 <a class="header-anchor" href="#_3-表头自定义设置" aria-label="Permalink to &quot;3.表头自定义设置&quot;">​</a></h4><ul><li>点击表头设置图标可更改表头字段的显示/隐藏</li></ul><h4 id="_4-详情" tabindex="-1">4.详情 <a class="header-anchor" href="#_4-详情" aria-label="Permalink to &quot;4.详情&quot;">​</a></h4><ul><li><p>点击&quot;详情&quot;按钮可查看此产品的基本信息，检验明细，检验准则</p></li><li><p>在检验明细中可查看检验报告，质检详情，质检报告等内容信息</p><p>-查看报告：点击可查看入库检验报告（可打印）</p><p>-质检详情：记录了质检的检验项，检验方法，检验要求，使用设备，检验结果</p><p>-质检报告：点击可查看质检时上传的报告</p></li></ul><h1 id="质检明细" tabindex="-1">质检明细 <a class="header-anchor" href="#质检明细" aria-label="Permalink to &quot;质检明细&quot;">​</a></h1><blockquote><p>质检明中记录着每个产品/物料检验的详细记录</p></blockquote><h4 id="_1-导出" tabindex="-1">1.导出 <a class="header-anchor" href="#_1-导出" aria-label="Permalink to &quot;1.导出&quot;">​</a></h4><ul><li><p>点击导出按钮分为两种导出样式</p><p>-先勾选需导出的内容，点击导出按钮选择第一个选项</p><p>-点击导出按钮，选择第二个选项，手动输入导入1~N条</p></li></ul><h4 id="_2-操作工" tabindex="-1">2.操作工 <a class="header-anchor" href="#_2-操作工" aria-label="Permalink to &quot;2.操作工&quot;">​</a></h4><ul><li>点击人员名称可查看这个操作工的基本信息</li></ul><p><img src="'+i+'" alt="rtss"></p><p><img src="'+r+'" alt="rtss"></p>',18)])])}const b=e(o,[["render",s]]);export{q as __pageData,b as default};
